+// ── Modal component logic ──────────────────────────────────────────────────
+
+const DeleteModal = (() => {
+  const overlay = document.getElementById('delete-modal-overlay');
+  const modal   = document.getElementById('delete-modal');
+
+  function open() {
+    overlay.classList.add('is-open');
+    overlay.setAttribute('aria-hidden', 'false');
+    modal.setAttribute('aria-hidden', 'false');
+    // Move focus into dialog
+    const firstFocusable = modal.querySelector('button, [href], input, [tabindex]:not([tabindex="-1"])');
+    if (firstFocusable) firstFocusable.focus();
+    document.body.style.overflow = 'hidden';
+  }
+
+  function close() {
+    overlay.classList.remove('is-open');
+    overlay.setAttribute('aria-hidden', 'true');
+    modal.setAttribute('aria-hidden', 'true');
+    document.body.style.overflow = '';
+    // Return focus to trigger
+    document.querySelector('.trigger')?.focus();
+  }
+
+  function handleDelete() {
+    // Simulate deletion feedback
+    const confirmBtn = document.getElementById('confirm-delete-btn');
+    confirmBtn.disabled = true;
+    confirmBtn.textContent = 'Deleting…';
+    setTimeout(() => {
+      close();
+      showToast();
+      confirmBtn.disabled = false;
+      confirmBtn.innerHTML = `
+        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
+          <polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/><path d="M10 11v6M14 11v6"/><path d="M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2"/>
+        </svg>
+        Delete Image`;
+    }, 900);
+  }
+
+  function showToast() {
+    const toast = document.getElementById('toast');
+    toast.classList.add('is-visible');
+    setTimeout(() => toast.classList.remove('is-visible'), 3200);
+  }
+
+  // ── Event wiring ──────────────────────────────────────────────────────────
+
+  // Open on trigger click
+  document.querySelectorAll('.trigger').forEach(el =>
+    el.addEventListener('click', open)
+  );
+
+  // Close on cancel / overlay click
+  document.getElementById('cancel-btn').addEventListener('click', close);
+  overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
+
+  // Close on Escape
+  document.addEventListener('keydown', e => {
+    if (e.key === 'Escape' && overlay.classList.contains('is-open')) close();
+  });
+
+  // Confirm delete
+  document.getElementById('confirm-delete-btn').addEventListener('click', handleDelete);
+
+  // Trap focus inside modal while open
+  modal.addEventListener('keydown', e => {
+    if (e.key !== 'Tab') return;
+    const focusable = Array.from(
+      modal.querySelectorAll('button:not([disabled]), [href], input, [tabindex]:not([tabindex="-1"])')
+    );
+    const first = focusable[0];
+    const last  = focusable[focusable.length - 1];
+    if (e.shiftKey) {
+      if (document.activeElement === first) { e.preventDefault(); last.focus(); }
+    } else {
+      if (document.activeElement === last)  { e.preventDefault(); first.focus(); }
+    }
+  });
+
+  return { open, close };
+})();
+
')
